export function createTimeScheduler() {
  const jobs = [];
  return {
    at(hhmm, fn) { jobs.push({ hhmm, fn }); },
    tick(now = new Date()) {
      const hm = now.getHours() * 60 + now.getMinutes();
      for (const job of jobs) {
        const [h, m] = job.hhmm.split(':').map(Number);
        if (h * 60 + m === hm) job.fn(now);
      }
    },
  };
}

