}

export function mergesort(arr, cmp = (a, b) => a - b) {
  const a = arr.slice();
  const aux = new Array(a.length);
  const merge = (lo, mid, hi) => {
    for (let k = lo; k <= hi; k++) aux[k] = a[k];
    let i = lo, j = mid + 1;
    for (let k = lo; k <= hi; k++) {
      if (i > mid) a[k] = aux[j++];
      else if (j > hi) a[k] = aux[i++];
      else a[k] = cmp(aux[j], aux[i]) < 0 ? aux[j++] : aux[i++];
    }
  };
